fn four_times(n: i32) -> i32 {
    4 * n
}

fn myfun(a: &mut Vec<i32>, sum: &mut Vec<i32>, N: i32) {
    // Update the only element of the second array to be four times N
    if sum.len() == 1 {
        sum[0] = four_times(N);
    }
}

